using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class TransportWorkTests
{
    static readonly EntityId Job=new("job:local-purse"),Player=new("created:carrier"),Issuer=new("person:shingen");
    internal static ContractWorld New()
    {
        var officers=new[]{new RegisteredOfficer(Player.Value,null,"運び手",1520,new(50,50,50,50),StartTemplate.Retainer,"castle:kofu",Issuer.Value,null),new RegisteredOfficer("created:recipient",null,"受取人",1520,new(50,50,50,50),StartTemplate.Retainer,"site:suwa",Issuer.Value,null)};
        var normalized=NewGameWorld.Normalize(officers);var preview=NewGameSetup.Preview(NewGameWorld.Scenario(),new(normalized,[]));Assert.True(preview.IsEligible(),string.Join(";",preview.Errors));
        return NewGameWorld.Create(preview.World!,normalized,Player.Value,42,NewGameWorld.CompactPersonalAuthority,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:NewGameWork.Policy);
    }
    static WorldSession Offer(){var s=new WorldSession(New());Assert.Equal(ResultCode.Accepted,s.RequestTransport(Job,s.Revision).Code);return s;}
    static TransportJob Current(WorldSession s)=>TransportWork.Jobs(s.DiagnosticSnapshot()).Single();
    internal static HandoverInput Input(WorldSession s,HandoverAction a){var j=Current(s);var t=j.Handover.Terms;var id=new EntityId("operation:transport/"+s.Revision);return new(id,a,a==HandoverAction.Cancel?t.Issuer:s.PlayerControl,a==HandoverAction.Deliver?t.Destination:t.Source,a==HandoverAction.Deliver?t.Recipient:a==HandoverAction.Cancel?t.Carrier:t.Issuer,a is HandoverAction.Collect or HandoverAction.Deliver or HandoverAction.Pay or HandoverAction.Return?new EntityId("transfer:transport/"+id.Value.Replace(':','/')):null,s.Seconds,j.Handover.Entries.Length);}
    static void Do(WorldSession s,HandoverAction a)=>Assert.Equal(ResultCode.Accepted,s.HandoverTransport(Job,Input(s,a),s.Revision).Code);
    static WorldSession Collected(){var s=Offer();Do(s,HandoverAction.Accept);Do(s,HandoverAction.Collect);return s;}
    internal static void Travel(WorldSession s,string to){var w=s.DiagnosticSnapshot();var i=TravelWorld.Move(w,"request:transport-trip/"+s.Revision,to);Assert.Equal(ResultCode.Accepted,s.Submit(i,s.Revision).Code);NewGameWorldTests.At(s,s.Seconds+100000);}
    [Fact]public void LegacyWorldHasNoTransportAndExactJsonRoundTrip(){var w=New();Assert.Null(w.TransportWork);Assert.DoesNotContain("TransportWork",System.Text.Encoding.UTF8.GetString(ContractJson.Write(w)));Assert.Equal(ContractJson.Write(w),ContractJson.Write(new WorldSession(w).DiagnosticSnapshot()));}
    [Fact]public void OfferPinsSameFactionInitialDestination(){var s=Offer();var t=Current(s).Handover.Terms;Assert.Equal("created:recipient",t.Recipient.Value);Assert.Equal("site:suwa",t.Destination.Value);Assert.Equal(1000,NewGameWork.Balance(s.DiagnosticSnapshot(),Issuer));Assert.Equal(0,s.DiagnosticSnapshot().ResourceLots.Single(l=>l.Id==TransportWork.Cargo(Job)).Quantity);}
    [Fact]public void CollectionMovesActualPrivateMoneyWithoutPayingCarrier(){var s=Collected();var w=s.DiagnosticSnapshot();Assert.Equal(900,NewGameWork.Balance(w,Issuer));Assert.Equal(1000,NewGameWork.Balance(w,Player));var cargo=w.ResourceLots.Single(l=>l.Id==TransportWork.Cargo(Job));Assert.Equal(100,cargo.Quantity);Assert.Equal(Issuer,cargo.Owner);Assert.Equal(Player,cargo.MobileHolder);Assert.Equal(w.ResourceLots.Sum(l=>l.InitialQuantity),w.ResourceLots.Sum(l=>l.Quantity));}
    [Fact]public void CannotDeliverFromSourceOrReportBeforeDelivery(){var s=Collected();var hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.HandoverTransport(Job,Input(s,HandoverAction.Deliver),s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.HandoverTransport(Job,Input(s,HandoverAction.Report),s.Revision).Code);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
    [Fact]public void RealTravelDeliveryReportAndFeeConserveMoney(){var s=Collected();Travel(s,"suwa");Do(s,HandoverAction.Deliver);Assert.Equal(0,s.DiagnosticSnapshot().ResourceLots.Single(l=>l.Id==TransportWork.Cargo(Job)).Quantity);Assert.Equal(100,s.DiagnosticSnapshot().ResourceLots.Single(l=>l.Id==TransportWork.Delivered(Job)).Quantity);Assert.Empty(s.DiagnosticSnapshot().Debts);Travel(s,"kofu");Do(s,HandoverAction.Report);Assert.Equal(20,Assert.Single(s.DiagnosticSnapshot().Debts).Outstanding);Do(s,HandoverAction.Pay);var w=s.DiagnosticSnapshot();Assert.Equal(1020,NewGameWork.Balance(w,Player));Assert.Equal(880,NewGameWork.Balance(w,Issuer));Assert.Equal(0,Assert.Single(w.Debts).Outstanding);Assert.Equal(w.ResourceLots.Sum(l=>l.InitialQuantity),w.ResourceLots.Sum(l=>l.Quantity));}
    [Fact]public void RetryOriginalPickupAfterWorldRestoreDoesNotDuplicateGoods(){var s=Collected();var old=Current(s).Handover.Entries.Last().Input;s=new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));string before=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.AlreadyAccepted,s.HandoverTransport(Job,old,s.Revision).Code);Assert.Equal(before,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));Assert.Equal(ResultCode.IdPayloadConflict,s.HandoverTransport(Job,old with{At=1},s.Revision).Code);}
    [Fact]public void LocalCancellationPreservesCargoUntilActualReturn(){var s=Collected();Do(s,HandoverAction.Cancel);Assert.Equal(100,s.DiagnosticSnapshot().ResourceLots.Single(l=>l.Id==TransportWork.Cargo(Job)).Quantity);Do(s,HandoverAction.Return);Assert.Equal(1000,NewGameWork.Balance(s.DiagnosticSnapshot(),Issuer));Assert.Empty(s.DiagnosticSnapshot().Debts);}
    [Theory][InlineData("quantity")][InlineData("owner")][InlineData("debt")][InlineData("revision")][InlineData("recipient")]
    public void ForgedSaveCannotInventStockOrReceipt(string change){var w=Collected().DiagnosticSnapshot();var lot=TransportWork.Cargo(Job);if(change=="quantity")w.ResourceLots=w.ResourceLots.Select(l=>l.Id==lot?l with{Quantity=101}:l).ToArray();if(change=="owner")w.ResourceLots=w.ResourceLots.Select(l=>l.Id==lot?l with{Owner=Player}:l).ToArray();if(change=="debt")w.Debts=[new(TransportWork.Debt(Job),Issuer,Player,"mon",20,TransportWork.Basis)];if(change=="revision"){var j=w.TransportWork!.Jobs[0];w.TransportWork=w.TransportWork with{Jobs=[j with{Receipts=j.Receipts.Select(p=>p with{Revision=1}).ToArray()}]};}if(change=="recipient"){var j=w.TransportWork!.Jobs[0];w.TransportWork=w.TransportWork with{Jobs=[j with{Handover=j.Handover with{Terms=j.Handover.Terms with{Recipient=Player}}}]};}Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void DuplicateDemandCannotCreateAnotherPurse(){var s=Collected();Assert.Equal(ResultCode.NotAvailable,s.RequestTransport(new("job:duplicate"),s.Revision).Code);Assert.Single(TransportWork.Jobs(s.DiagnosticSnapshot()));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)]public void GenerationSaveRestoresCargoAndSameContinuation(int phase){var s=Offer();if(phase>0)Do(s,HandoverAction.Accept);if(phase>1)Do(s,HandoverAction.Collect);if(phase>2){Travel(s,"suwa");Do(s,HandoverAction.Deliver);}if(phase>3){Travel(s,"kofu");Do(s,HandoverAction.Report);}if(phase>4)Do(s,HandoverAction.Pay);s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"transport-world-"+Guid.NewGuid().ToString("N")),w.Definitions);store.Save(s,"manual",w.WorldId,new(0,1));var host=new WorldSessionHost(new(New()));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("manual"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.CanonicalHash(w),ContractJson.CanonicalHash(host.Current.DiagnosticSnapshot()));NewGameWorldTests.At(s,s.Seconds+1);NewGameWorldTests.At(host.Current,host.Current.Seconds+1);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(host.Current.DiagnosticSnapshot()));}

    [Fact]public void CannotPayBeforeReturningWithReport(){var s=Collected();Assert.Equal(ResultCode.NotAvailable,s.HandoverTransport(Job,Input(s,HandoverAction.Pay),s.Revision).Code);Assert.Empty(s.DiagnosticSnapshot().Debts);Assert.Equal(1000,NewGameWork.Balance(s.DiagnosticSnapshot(),Player));}
    [Fact]public void SameJobIdentifierCannotBecomeReceipt(){var s=Offer();var i=Input(s,HandoverAction.Accept) with{Id=Job};Assert.Equal(ResultCode.IdPayloadConflict,s.HandoverTransport(Job,i,s.Revision).Code);}
    [Fact]public void StaleWorldRevisionCannotAccept(){var s=Offer();Assert.Equal(ResultCode.StateChanged,s.HandoverTransport(Job,Input(s,HandoverAction.Accept),s.Revision-1).Code);Assert.Empty(Current(s).Handover.Entries);}
    [Fact]public void MidJourneyRealGenerationRestoreKeepsCargoAndSameArrival(){var s=Collected();Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:mid-transport","suwa"),s.Revision).Code);NewGameWorldTests.At(s,3);s.SetPaused(true);var w=s.DiagnosticSnapshot();Assert.Equal(LocationKind.Traveling,w.Locations.Single(l=>l.Actor==Player).Kind);var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"transport-mid-"+Guid.NewGuid().ToString("N")),w.Definitions);store.Save(s,"manual",w.WorldId,new(0,1));var host=new WorldSessionHost(new(New()));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("manual"),host.Current,host.Current.Revision));NewGameWorldTests.At(s,100000);NewGameWorldTests.At(host.Current,100000);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(host.Current.DiagnosticSnapshot()));Do(s,HandoverAction.Deliver);Do(host.Current,HandoverAction.Deliver);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(host.Current.DiagnosticSnapshot()));}
    [Fact]public void PickupDoesNotAllowUnregisteredStockProof(){var s=Offer();Do(s,HandoverAction.Accept);Assert.Equal(ResultCode.NotAvailable,s.HandoverTransport(Job,Input(s,HandoverAction.Collect) with{Transaction=new("transfer:imaginary")},s.Revision).Code);Assert.Equal(1000,NewGameWork.Balance(s.DiagnosticSnapshot(),Issuer));}
    [Fact]public void RemoteIssuerCannotCancelOrTeleportBackCargo(){var s=Collected();Travel(s,"suwa");Assert.Equal(ResultCode.NotAvailable,s.HandoverTransport(Job,Input(s,HandoverAction.Cancel),s.Revision).Code);Assert.Equal(100,s.DiagnosticSnapshot().ResourceLots.Single(l=>l.Id==TransportWork.Cargo(Job)).Quantity);}
    [Fact]public void LiteralOldSavesStillOmitTransport(){foreach(var n in new[]{"initial","active"}){var b=File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory,"Fixtures","military-bd631ba-"+n+".json"));var w=ContractJson.Read<ContractWorld>(b);ContractValidation.Validate(w);Assert.Null(w.TransportWork);Assert.Equal(b,ContractJson.Write(w));}}
}
